import { _decorator, Component, Sprite, Color } from 'cc';
import type { EntityView } from '../../Engine/ViewRegistry';
import type { Entity } from '../../Engine/Entity';
import type { GhostEntity } from '../Entity/GhostEntity';
const { ccclass } = _decorator;


@ccclass('GhostView')
export class GhostView extends Component implements EntityView {
    private _ghost: GhostEntity = null!;
    private _sprite: Sprite = null!;

    onLoad() {
        this._sprite = this.getComponent(Sprite)!;
    }

    bind(entity: Entity): void {
        this._ghost = entity as GhostEntity;
    }

    sync(dt: number): void {
        if (!this._ghost) return;

        this.node.active = this._ghost.active;
        if (!this._ghost.active) return;

        // 坐标在 GhostSystem 里已经算好了
        this.node.setPosition(this._ghost.x, this._ghost.y);

        if (this._ghost.valid) {
            this._sprite.color = new Color(100, 255, 100, 150);
        } else {
            this._sprite.color = new Color(255, 100, 100, 150);
        }
    }

    unbind(): void {
        this._ghost = null!;
    }
}